use std::{fs, path::PathBuf, process::ExitCode};

const BARREL: &str =
    "// Generated by `pnpm gen:wire-types`. Do not edit.\nexport * from './generated'\n";

fn main() -> ExitCode {
    let dir = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../src/shared/state/generated");
    let ts = match tatsu_state::export_typescript(tatsu_state::wire_types()) {
        Ok(ts) => ts,
        Err(err) => {
            eprintln!("gen-wire-types: {err}");
            return ExitCode::FAILURE;
        }
    };
    let written = fs::create_dir_all(&dir)
        .and_then(|()| fs::write(dir.join("generated.ts"), ts))
        .and_then(|()| fs::write(dir.join("index.ts"), BARREL));
    if let Err(err) = written {
        eprintln!("gen-wire-types: {}: {err}", dir.display());
        return ExitCode::FAILURE;
    }
    ExitCode::SUCCESS
}
